{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import * as readline from 'readline';

// Parse arguments
const mode = process.argv[2];
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n');
  process.exit(2);
}

// Read input from stdin
let input = '';
const rl = readline.createInterface({ input: process.stdin });

rl.on('line', (line) => {
  input += line + '\n';
});

rl.on('close', () => {
  try {
    processInput(input);
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`);
    process.exit(2);
  }
});

function processInput(input) {
  // Parse documents
  const parts = input.split('%%%\n');
  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%');
  }

  // Parse each document
  const parseDoc = (part) => {
    if (part === '' || part === '\n') return [];
    const lines = part.split('\n');
    if (lines[lines.length - 1] === '') {
      lines.pop();
    }
    return lines;
  };

  const mine = parseDoc(parts[0]);
  const base = parseDoc(parts[1]);
  const theirs = parseDoc(parts[2]);

  // Compute LCS for mine vs base and theirs vs base
  const mineChanges = computeChanges(mine, base);
  const theirsChanges = computeChanges(theirs, base);

  // Merge changes
  const result = mergeChanges(mine, base, theirs, mineChanges, theirsChanges, mode);

  // Output result
  const { output, hasConflict } = result;
  process.stdout.write(output);
  process.exit(hasConflict ? 1 : 0);
}

function computeLCS(a, b) {
  // Compute LCS with early-match preference
  const n = a.length;
  const m = b.length;

  // Build DP table for LCS length
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Reconstruct LCS with early-match preference
  const lcs = [];
  let i = n;
  let j = m;

  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      lcs.unshift({ i: i - 1, j: j - 1 });
      i--;
      j--;
    } else {
      // When sequences are equally long, advance the side with at least as long remaining
      // Prefer to advance base (j) when they tie
      const aRemaining = i;
      const bRemaining = j;

      if (bRemaining > aRemaining) {
        j--;
      } else {
        i--;
      }
    }
  }

  return lcs;
}

function computeChanges(side, base) {
  const lcs = computeLCS(side, base);
  const changes = [];

  // Build a set of matched indices in base
  const baseMatched = new Set();
  const sideMatched = new Set();
  lcs.forEach(({ i, j }) => {
    sideMatched.add(i);
    baseMatched.add(j);
  });

  // Track coverage
  let lastBaseEnd = 0;
  let lastSideEnd = 0;

  lcs.forEach(({ i, j }) => {
    // Collect unmatched lines in base from lastBaseEnd to j
    const baseStart = lastBaseEnd;
    const baseEnd = j;
    const sideStart = lastSideEnd;
    const sideEnd = i;

    if (baseStart < baseEnd || sideStart < sideEnd) {
      changes.push({
        baseStart,
        baseEnd,
        sideStart,
        sideEnd,
        side: side.slice(sideStart, sideEnd)
      });
    }

    lastBaseEnd = j + 1;
    lastSideEnd = i + 1;
  });

  // Handle trailing unmatched lines
  if (lastBaseEnd < base.length || lastSideEnd < side.length) {
    changes.push({
      baseStart: lastBaseEnd,
      baseEnd: base.length,
      sideStart: lastSideEnd,
      sideEnd: side.length,
      side: side.slice(lastSideEnd, side.length)
    });
  }

  return changes;
}

function mergeChanges(mine, base, theirs, mineChanges, theirsChanges, mode) {
  // Merge the change lists
  const allChanges = [];

  mineChanges.forEach(change => {
    allChanges.push({ ...change, source: 'mine' });
  });

  theirsChanges.forEach(change => {
    allChanges.push({ ...change, source: 'theirs' });
  });

  // Sort by base start position, with mine before theirs when equal
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart;
    return a.source === 'mine' ? -1 : 1;
  });

  // Process regions
  const regions = [];
  let lastBaseEnd = 0;

  while (allChanges.length > 0) {
    const firstChange = allChanges.shift();
    let regionBaseStart = firstChange.baseStart;
    let regionBaseEnd = firstChange.baseEnd;

    // Absorb overlapping changes
    while (allChanges.length > 0 && allChanges[0].baseStart <= regionBaseEnd) {
      const nextChange = allChanges.shift();
      regionBaseEnd = Math.max(regionBaseEnd, nextChange.baseEnd);
    }

    // If there's a stable region before this change region, add it
    if (lastBaseEnd < regionBaseStart) {
      regions.push({
        type: 'stable',
        baseStart: lastBaseEnd,
        baseEnd: regionBaseStart,
        lines: base.slice(lastBaseEnd, regionBaseStart)
      });
    }

    // Collect all changes that touch this region
    const regionStart = regionBaseStart;
    const regionEnd = regionBaseEnd;

    // Re-collect changes for this region
    const touchingChanges = [firstChange];
    const remaining = [];

    allChanges.forEach(change => {
      if (change.baseStart < regionEnd) {
        touchingChanges.push(change);
        regionBaseEnd = Math.max(regionBaseEnd, change.baseEnd);
      } else {
        remaining.push(change);
      }
    });
    allChanges = remaining;

    // Process the region
    const mineInRegion = touchingChanges.filter(c => c.source === 'mine');
    const theirsInRegion = touchingChanges.filter(c => c.source === 'theirs');

    if (mineInRegion.length === 0) {
      // Only theirs changed
      const replacement = assembleReplacement(theirsInRegion, regionStart, regionEnd, base);
      regions.push({
        type: 'theirs',
        lines: replacement
      });
    } else if (theirsInRegion.length === 0) {
      // Only mine changed
      const replacement = assembleReplacement(mineInRegion, regionStart, regionEnd, base);
      regions.push({
        type: 'mine',
        lines: replacement
      });
    } else {
      // Both sides changed - resolve conflict
      const mineReplacement = assembleReplacement(mineInRegion, regionStart, regionEnd, base);
      const theirsReplacement = assembleReplacement(theirsInRegion, regionStart, regionEnd, base);
      const baseRegion = base.slice(regionStart, regionEnd);

      if (JSON.stringify(mineReplacement) === JSON.stringify(theirsReplacement)) {
        regions.push({
          type: 'both',
          lines: mineReplacement
        });
      } else if (JSON.stringify(mineReplacement) === JSON.stringify(baseRegion)) {
        regions.push({
          type: 'theirs',
          lines: theirsReplacement
        });
      } else if (JSON.stringify(theirsReplacement) === JSON.stringify(baseRegion)) {
        regions.push({
          type: 'mine',
          lines: mineReplacement
        });
      } else {
        regions.push({
          type: 'conflict',
          mine: mineReplacement,
          base: baseRegion,
          theirs: theirsReplacement
        });
      }
    }

    lastBaseEnd = regionBaseEnd;
  }

  // Add final stable region if needed
  if (lastBaseEnd < base.length) {
    regions.push({
      type: 'stable',
      lines: base.slice(lastBaseEnd, base.length)
    });
  }

  // Generate output
  let output = '';
  let hasConflict = false;

  if (mode === 'merge' || mode === 'merge2') {
    regions.forEach(region => {
      if (region.type === 'stable') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'mine') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'theirs') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'both') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'conflict') {
        hasConflict = true;
        output += '<<<<<<< mine\n';
        output += region.mine.map(l => l + '\n').join('');
        if (mode === 'merge') {
          output += '||||||| base\n';
          output += region.base.map(l => l + '\n').join('');
        }
        output += '=======\n';
        output += region.theirs.map(l => l + '\n').join('');
        output += '>>>>>>> theirs\n';
      }
    });
  } else if (mode === 'regions') {
    regions.forEach(region => {
      if (region.type === 'stable') {
        output += `stable ${region.lines.length}\n`;
      } else if (region.type === 'mine') {
        output += `mine ${region.lines.length}\n`;
      } else if (region.type === 'theirs') {
        output += `theirs ${region.lines.length}\n`;
      } else if (region.type === 'both') {
        output += `both ${region.lines.length}\n`;
      } else if (region.type === 'conflict') {
        hasConflict = true;
        output += `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`;
      }
    });
  }

  return { output, hasConflict };
}

function assembleReplacement(changes, regionStart, regionEnd, base) {
  // For a region several changes touch, each side's replacement runs from
  // the smallest start of its own changes, moved back by however far the
  // region begins before those changes do in the base, to the largest end
  // of its own changes, moved forward by however far the region ends after them.

  if (changes.length === 0) {
    return [];
  }

  // Find the extent of changes
  let minChangeStart = Math.min(...changes.map(c => c.baseStart));
  let maxChangeEnd = Math.max(...changes.map(c => c.baseEnd));

  // Adjust for region boundaries
  const backOffset = minChangeStart - regionStart;
  const forwardOffset = regionEnd - maxChangeEnd;

  // Assemble the replacement
  let result = [];

  changes.forEach(change => {
    result = result.concat(change.side);
  });

  return result;
}
