const rl = readline.createInterface({ input: process.stdin });

rl.on('line', (line) => {
  input += line + '\n';
});

rl.on('close', () => {
  try {
    processInput(input);
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`);
    process.exit(2);
  }
});

function processInput(input) {
  // Parse documents
  const parts = input.split('%%%\n');
  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%');
  }

  // Parse each document
  const parseDoc = (part) => {
    if (part === '' || part === '\n') return [];
    const lines = part.split('\n');
    if (lines[lines.length - 1] === '') {
      lines.pop();
    }
    return lines;
  };

  const mine = parseDoc(parts[0]);
  const base = parseDoc(parts[1]);
  const theirs = parseDoc(parts[2]);

  // Compute changes for each side vs base
  const mineChanges = computeChanges(mine, base);
  const theirsChanges = computeChanges(theirs, base);

  // Merge and output result
  const { output, hasConflict } = performMerge(mine, base, theirs, mineChanges, theirsChanges, mode);
  process.stdout.write(output);
  process.exit(hasConflict ? 1 : 0);
}

// Compute LCS with early-match preference
function computeLCS(a, b) {
  const n = a.length;
  const m = b.length;

  // Build DP table for LCS length
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Reconstruct LCS with early-match preference
  const lcs = [];
  let i = n;
  let j = m;

  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      lcs.unshift({ i: i - 1, j: j - 1 });
      i--;
      j--;
    } else {
      // When sequences are equally long, advance the side with at least as long remaining
      // Prefer to advance base (j) when they tie
      if (j > i) {
        j--;
      } else {
        i--;
      }
    }
  }

  return lcs;
}

// Convert LCS to list of changes
function computeChanges(side, base) {
  const lcs = computeLCS(side, base);
  const changes = [];

  let lastSidePos = 0;
  let lastBasePos = 0;

  for (const { i, j } of lcs) {
    // Create a change for the gap before this match if there is a gap
    if (lastSidePos < i || lastBasePos < j) {
      changes.push({
        baseStart: lastBasePos,
        baseEnd: j,
        sideStart: lastSidePos,
        sideEnd: i,
        side: side.slice(lastSidePos, i)
